SUSPENSION VOLUNTARIA: Estar al dia y dar fecha de retiro del equipo.

HORARIO: Lun-Vie 8am-12pm y 1pm-5pm. Sab 8am-12pm.
OFICINA: Cra 19 #20-50, Int 202, Parque principal, San Luis.
WHATSAPP: 3185191300.`;

let clientContext = '';
try {
  const wh = $('Buscar en WispHub').first().json;
  const results = wh?.results || [];
  if (results.length > 0) {
    const c = results[0];
    clientContext = `DATOS DEL CLIENTE (WispHub):
- Nombre: ${c.nombre || c.usuario || 'N/D'}
- Plan: ${c.plan_internet_nombre || c.plan_internet || 'N/D'}
- Estado: ${c.estado || 'N/D'}
- Zona: ${c.zona_nombre || c.zona || 'N/D'}
- ID servicio: ${c.id || 'N/D'}`;
  } else {
    clientContext = 'Este numero NO esta registrado como cliente. Puede ser un interesado.';
  }
} catch (e) {
  clientContext = 'No se pudo consultar WispHub. Responde con la base de conocimiento.';
}

const prev = $('Extraer mensaje').first().json;
const fullSystem = `${instrucciones}

---
${conocimiento}

---
${clientContext}`;

return [{
  json: {
    system: fullSystem,
    userMessage: `${prev.clientName} dice: "${prev.messageText}"`,
    phoneConCodigo: prev.phoneConCodigo,
    phoneNumberId: prev.phoneNumberId
  }
}];

const claudeResponse = $input.first().json;
const textBlock = claudeResponse.content?.find(b => b.type === 'text');
let replyText = textBlock?.text || 'Lo siento, no pude procesar su mensaje. Un asesor le ayudara en breve.';

const shouldEscalate = replyText.includes('[ESCALAR_A_HUMANO]');
replyText = replyText.replace('[ESCALAR_A_HUMANO]', '').trim();

if (replyText.length > 4000) {
  replyText = replyText.substring(0, 3997) + '...';
}

return [{
  json: {
    replyText,
    shouldEscalate,
    phoneConCodigo: $('Construir prompt').first().json.phoneConCodigo,
    phoneNumberId: $('Construir prompt').first().json.phoneNumberId
  }
}];
